import mqtt from 'mqtt';

const MQTT_BROKER = 'wss://broker.emqx.io:8084/mqtt';
const MQTT_TOPIC = 'esp/siren';

const publishMQTT = (message) => {
  return new Promise((resolve) => {
    try {
      const client = mqtt.connect(MQTT_BROKER, {
        clientId: 'webapp_' + Math.random().toString(36).substr(2, 9),
        clean: true,
        connectTimeout: 5000,
      });

      client.on('connect', () => {
        client.publish(MQTT_TOPIC, message, { qos: 1 }, () => {
          client.end();
          resolve(true);
        });
      });

      client.on('error', (err) => {
        console.error('MQTT error:', err);
        client.end();
        resolve(false);
      });

      setTimeout(() => {
        client.end();
        resolve(false);
      }, 6000);
    } catch (e) {
      console.error('MQTT connect failed:', e);
      resolve(false);
    }
  });
};

export const triggerSiren = () => publishMQTT('ON');
export const stopSiren = () => publishMQTT('OFF');
